import React, { useState } from 'react'
import Modal from 'react-modal'
import axios from "axios"
import { CopyPlus, X } from 'lucide-react'
import { Toaster, toast } from 'sonner'
import './AddNewGroup.scss'

Modal.setAppElement('#root')

const AddNewGroup = () => {
    const [isOpen, setIsOpen] = useState(false)
    
    const openModal = () => {
        setIsOpen(true)
    }
    
    const closeModal = () => {
        setGroup(initialFormData)
        setIsOpen(false)
    }

    const initialFormData = {
        groupName:"",
        maxCapacity:""
    }

    const [group, setGroup] = useState(initialFormData)
    const [limited, setLimited] = useState(false)

    const handleChange = (event) => {
        setGroup({
            ...group,
            [event.target.id]: event.target.value,
        })
    }

    const handleSubmit = async (event) => {
        event.preventDefault();

        try {
            // Check if the group already exists
            const { data: existinggroup } = await axios.get("http://localhost:8800/group", {
                params: { firstname: group.firstname, lastname: group.lastname, email: group.email }
            })

            if (existinggroup.length > 0) {
                toast.error(`${group.firstname} ${group.lastname} is already added`)
                setgroup(initialFormData)
            } else {
                // Add the new group
                await axios.post("http://localhost:8800/group", group)
                toast.success(`Successfully added ${group.firstname} ${group.lastname}`)
                closeModal()
            }
        } catch (error) {
            if (error.response && error.response.status === 409) {
                toast.error(`Error: ${error.response.data.error}`)
            } else {
                console.error('Failed to add group:', error)
                toast.error('Failed to add group')
            }
        }
    }

    return (
        <div className="add-group-container">
            <button className="add-group" type="button" onClick={openModal}>
                <CopyPlus />
            </button>
            <Modal
                className='modal-add'
                overlayClassName="modal-overlay"
                isOpen={isOpen}
                onRequestClose={closeModal}
                contentLabel="Example Modal"
            >
                <div className='modal-input-container'>
                    <h2 className='subtitle'>Add New Group</h2>
                    <X className='modal-close' onClick={closeModal} />
                    <form className='modal-form' onSubmit={handleSubmit}>
                        <div className='input-wrapper'>
                            <label>Group Name</label>
                            <input 
                                type='text'
                                id='groupName'
                                value={group.groupName}
                                placeholder='First Name'
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className='input-wrapper'>
                            <label>Limit Capacity</label>
                            <input
                                type='radio'
                                id='limitCapacity'
                                value={limte}
                            />
                        </div>
                        <div className='input-wrapper'>
                            <label>Max Capacity</label>
                            <input 
                                type='number'
                                id='maxCapacity'
                                value={group.maxCapacity}
                                placeholder='Maximum Capacity'
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className='button-wrapper'>
                            <button className='modal-cancel-button' onClick={closeModal}>Cancel</button>
                            <button className='modal-add-button'>Save</button>
                        </div>
                    </form>
                </div>
            </Modal>
        </div>
    )
}

export default AddNewGroup
